INSERT INTO `locations` VALUES (2,'LOC-002','place_4','locations/Screenshot_2025-05-15_160656.png',16.840900,96.173500,'this is for testing','Yangon','2026-06-11',NULL,NULL,NULL),(6,'LOC-006','place_1','locations/Screenshot_2025-05-15_160656_J2npYhz.png',16.838655,96.172317,'This is for testing','Yangon','2026-07-01',NULL,'ကုန်းတွင်းရေနံမြေများ',NULL),(7,'LOC-007','place_2','locations/Screenshot_2025-05-14_131915.png',18.911258,96.465627,'This is for testing','Taungoo','2026-07-01',NULL,'',NULL),(8,'LOC-008','place_3','locations/Screenshot_2025-05-14_132309.png',18.892615,96.477060,'This is for testing','Taungoo','2026-07-01',NULL,'မြေပုံများ',NULL),(10,'LOC-010','ရခိုင်ကမ်းလွန် Block A-1 (ရွှေသဘာဝဓာတ်ငွေ့ဖွံ့ဖြိုးရေး)','locations/location_2_Rakhine.jpg',20.147117,92.836497,'ရခိုင်ကမ်းလွန် Block A-1 တွင် ရွှေသဘာဝဓာတ်ငွေ့ဖွံ့ဖြိုးရေး အဆင့်၂ ကမ်းလွန်တည်ဆောက်ရေးစီမံကိန်း Phase-2 Development EPCIC (Offshore Installation) Project ဆောင်ရွက်နေသည့် DSV. Lichtenstein သင်္ဘောအား မြင်တွေ့ရစဉ်။','Sittwe','2026-03-05',NULL,'ကမ်းလွန်ရေနံလုပ်ကွက်များ','Rakhine State'),(11,'LOC-011','မုတ္တမကမ်းလွန် Block M-9','locations/location_3_MTM.jpg',16.592341,96.995524,'မုတ္တမကမ်းလွန် Block M-9 တွင် NCB Drilling Rig ဖြင့် ရေနံနှင့်သဘာဝဓာတ်ငွေ့ ရှာဖွေတူးဖော်ရေးလုပ်ငန်းများဆောင်ရွက်ခဲ့စဉ်','Mottama','2026-07-01',NULL,'ကမ်းလွန်ရေနံလုပ်ကွက်များ','Ayawady Division'),(12,'LOC-012','Shwe Drilling & Production Platform','locations/location_5_Rakhine_3.jpg',19.937442,92.604119,'ရခိုင်ကမ်းလွန် Block A-1/A-3 တွင် သဘာဝဓာတ်ငွေ့ထုတ်လုပ်ရေးလုပ်ငန်းများဆောင်ရွက်နေသည့် Shwe Drilling & Production Platform ကိုတွေ့ရပုံ','Sittwe','2025-09-04',NULL,'ကမ်းလွန်ရေနံလုပ်ကွက်များ','Rakhine State'),(13,'LOC-013','MOGE တွင် ပြုလုပ်ခဲ့သည့် DAMS အစည်းအဝေးမှတ်တမ်း','locations/location_6_meeting.jpg',19.751206,96.093261,'Document Archiving Management System Project အကြောင်း ဆွေးနွေးတင်ပြခြင်း','NayPyiTaw','2026-05-08',NULL,'မှတ်တမ်းဓာတ်ပုံများ','NayPyiTaw');
